You are implementing Task 2.3: Audio System

## Task Description

Create the audio system for Vibe Voyager using Howler.js. The system manages ambient space music and UI sound effects.

### Files to Create

**1. `lib/audio.ts`** — Singleton audio manager:

```typescript
import { Howl, Howler } from 'howler'

type SFXName = 'click' | 'hover' | 'warp' | 'mission-complete' | 'dialogue-blip' | 'success' | 'error' | 'rank-up'

class AudioManager {
  private ambient: Howl | null = null
  private sfx: Map<SFXName, Howl> = new Map()
  private _muted: boolean = false
  private _volume: number = 0.5
  private initialized: boolean = false

  init() {
    if (this.initialized) return
    this.initialized = true

    // Load mute preference
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem('vibe-voyager-muted')
      this._muted = saved === 'true'
      Howler.mute(this._muted)
    }
  }

  private getOrCreateSFX(name: SFXName): Howl {
    if (!this.sfx.has(name)) {
      this.sfx.set(name, new Howl({
        src: [`/audio/sfx/${name}.mp3`],
        volume: this._volume,
        preload: true,
      }))
    }
    return this.sfx.get(name)!
  }

  playAmbient() {
    if (!this.ambient) {
      this.ambient = new Howl({
        src: ['/audio/ambient-space.mp3'],
        loop: true,
        volume: this._volume * 0.3, // ambient is quieter
        preload: true,
      })
    }
    if (!this.ambient.playing()) {
      this.ambient.play()
    }
  }

  stopAmbient() {
    this.ambient?.stop()
  }

  playSFX(name: SFXName) {
    if (this._muted) return
    try {
      const sound = this.getOrCreateSFX(name)
      sound.play()
    } catch {
      // Silently fail if audio file doesn't exist yet
    }
  }

  setVolume(volume: number) {
    this._volume = Math.max(0, Math.min(1, volume))
    Howler.volume(this._volume)
  }

  toggleMute(): boolean {
    this._muted = !this._muted
    Howler.mute(this._muted)
    if (typeof window !== 'undefined') {
      localStorage.setItem('vibe-voyager-muted', String(this._muted))
    }
    return this._muted
  }

  get muted() {
    return this._muted
  }

  get volume() {
    return this._volume
  }
}

// Singleton
export const audio = new AudioManager()
```

**2. `components/audio/AudioManager.tsx`** — React component:

```tsx
'use client'

import { createContext, useContext, useState, useEffect, useCallback, ReactNode } from 'react'
import { audio } from '@/lib/audio'

interface AudioContextType {
  muted: boolean
  toggleMute: () => void
  playSFX: (name: string) => void
}

const AudioContext = createContext<AudioContextType>({
  muted: false,
  toggleMute: () => {},
  playSFX: () => {},
})

export function AudioProvider({ children }: { children: ReactNode }) {
  const [muted, setMuted] = useState(false)
  const [userInteracted, setUserInteracted] = useState(false)

  useEffect(() => {
    audio.init()
    setMuted(audio.muted)

    // Start ambient audio on first user interaction (browser autoplay policy)
    const handleInteraction = () => {
      if (!userInteracted) {
        setUserInteracted(true)
        audio.playAmbient()
      }
    }

    window.addEventListener('click', handleInteraction, { once: true })
    window.addEventListener('keydown', handleInteraction, { once: true })

    return () => {
      window.removeEventListener('click', handleInteraction)
      window.removeEventListener('keydown', handleInteraction)
    }
  }, [userInteracted])

  const toggleMute = useCallback(() => {
    const newMuted = audio.toggleMute()
    setMuted(newMuted)
    if (newMuted) {
      audio.stopAmbient()
    } else {
      audio.playAmbient()
    }
  }, [])

  const playSFX = useCallback((name: string) => {
    audio.playSFX(name as any)
  }, [])

  return (
    <AudioContext.Provider value={{ muted, toggleMute, playSFX }}>
      {children}
    </AudioContext.Provider>
  )
}

export function useAudio() {
  return useContext(AudioContext)
}

export function AudioToggle() {
  const { muted, toggleMute } = useAudio()

  return (
    <button
      onClick={toggleMute}
      className="p-2 text-starlight-dim hover:text-starlight transition-colors"
      [REDACTED_PROJECT]-label={muted ? 'Unmute audio' : 'Mute audio'}
    >
      {muted ? (
        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
          <path d="M11 5L6 9H2v6h4l5 4V5z" />
          <line x1="23" y1="9" x2="17" y2="15" />
          <line x1="17" y1="9" x2="23" y2="15" />
        </svg>
      ) : (
        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
          <polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5" />
          <path d="M19.07 4.93a10 10 0 0 1 0 14.14" />
          <path d="M15.54 8.46a5 5 0 0 1 0 7.07" />
        </svg>
      )}
    </button>
  )
}
```

**3. Create placeholder audio files:**

```bash
mkdir -p public/audio/sfx
# Create minimal valid MP3 files (silent) as placeholders
# We'll use empty files for now — Howler.js will fail silently
touch public/audio/ambient-space.mp3
touch public/audio/sfx/click.mp3
touch public/audio/sfx/hover.mp3
touch public/audio/sfx/warp.mp3
touch public/audio/sfx/mission-complete.mp3
touch public/audio/sfx/dialogue-blip.mp3
touch public/audio/sfx/success.mp3
touch public/audio/sfx/error.mp3
touch public/audio/sfx/rank-up.mp3
```

### Verification

The audio system should initialize without errors even with empty placeholder files (Howler fails silently). Verify `npm run dev` has no console errors related to audio imports.

### Commit

```bash
git add lib/audio.ts components/audio/ public/audio/
git commit -m "feat: implement Howler.js audio system with SFX and ambient support

Co-Authored-By: Claude Opus 4.6 <noreply@anthropic.com>"
```

## Context

Phase 2 of Vibe Voyager. This audio system will be used by all game screens for UI feedback (button clicks, warp sounds, mission completion chimes). Other agents are building game state, UI components, and data layer in parallel. Actual audio files will be sourced later in Phase 8 — for now, placeholders are fine.

